SET LOCAL statement_timeout = '60s';
SET LOCAL jit = off;
CREATE TABLE IF NOT EXISTS ms_existencias_hist (fecha DATE NOT NULL, base TEXT NOT NULL, almacen_id BIGINT NOT NULL, almacen TEXT,
  articulo_id BIGINT NOT NULL, clave TEXT, articulo TEXT, existencia NUMERIC, valor NUMERIC, guardado TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY (fecha, base, almacen_id, articulo_id));
INSERT INTO ms_existencias_hist (fecha, base, almacen_id, almacen, articulo_id, clave, articulo, existencia, valor)
SELECT DISTINCT ON (coalesce(e.base, ''), coalesce(e.almacen_id, 0), e.articulo_id)
       (now() AT TIME ZONE 'America/Mexico_City')::date, coalesce(e.base, ''), coalesce(e.almacen_id, 0), e.almacen,
       e.articulo_id, e.clave, e.articulo, e.existencia, e.valor
FROM ms_existencias e WHERE e.articulo_id IS NOT NULL
ORDER BY coalesce(e.base, ''), coalesce(e.almacen_id, 0), e.articulo_id, e.actualizado DESC
ON CONFLICT (fecha, base, almacen_id, articulo_id) DO UPDATE SET existencia = EXCLUDED.existencia, valor = EXCLUDED.valor,
  almacen = EXCLUDED.almacen, clave = EXCLUDED.clave, articulo = EXCLUDED.articulo, guardado = now();

CREATE TABLE IF NOT EXISTS tablero_acceso (token TEXT PRIMARY KEY, rol TEXT NOT NULL, activo BOOLEAN NOT NULL DEFAULT true, creado TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO tablero_acceso (token, rol) SELECT md5(random()::text || clock_timestamp()::text || v.r), v.r FROM (VALUES ('compras'), ('auditor')) AS v(r)
WHERE NOT EXISTS (SELECT 1 FROM tablero_acceso a WHERE a.rol = v.r AND a.activo);
SELECT (SELECT token FROM tablero_acceso WHERE rol = 'compras' AND activo ORDER BY creado LIMIT 1) AS t_compras,
       (SELECT token FROM tablero_acceso WHERE rol = 'auditor' AND activo ORDER BY creado LIMIT 1) AS t_auditor,
       (SELECT token FROM tablero_acceso WHERE rol = 'admin' AND activo ORDER BY creado LIMIT 1) AS t_admin;

